@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700;800&family=Unbounded:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --app-vh: 1vh;
  --brand-50: 250 245 255;
  --brand-100: 243 232 255;
  --brand-200: 233 213 255;
  --brand-300: 216 180 254;
  --brand-400: 192 132 252;
  --brand-500: 168 85 247;
  --brand-600: 147 51 234;
  --brand-700: 126 34 206;
  --brand-800: 107 33 168;
  --brand-900: 88 28 135;
  --ink: 15 23 42;
  --ink-soft: 71 85 105;
  --surface: 255 255 255;
  --surface-soft: 248 250 252;
  --surface-tint: 250 245 255;
  --ring: 168 85 247;
  --shadow-soft: 0 12px 34px rgba(15, 23, 42, 0.10), 0 2px 8px rgba(148, 163, 184, 0.16);
  --shadow-panel: 0 8px 26px rgba(15, 23, 42, 0.07), 0 1px 2px rgba(148, 163, 184, 0.24);
  --shadow-lift: 0 22px 56px rgba(79, 70, 229, 0.18), 0 10px 30px rgba(15, 23, 42, 0.10);
}

@layer base {
  html {
    font-family: "Manrope", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    color: rgb(var(--ink));
    background-color: rgb(var(--surface-soft));
    line-height: 1.45;
    scroll-behavior: smooth;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  body {
    min-height: 100%;
    background-color: rgb(var(--surface-soft));
    background-image:
      radial-gradient(circle at 15% -10%, rgba(236, 72, 153, 0.08), transparent 35%),
      radial-gradient(circle at 85% -20%, rgba(59, 130, 246, 0.08), transparent 38%),
      linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(241, 245, 249, 0.92));
    background-attachment: fixed;
  }

  #root {
    min-height: 100%;
  }

  h1, h2, h3, .font-display {
    font-family: "Unbounded", "Manrope", system-ui, sans-serif;
    letter-spacing: -0.01em;
  }

  input:focus-visible,
  textarea:focus-visible,
  select:focus-visible,
  button:focus-visible {
    outline: none;
    border-color: rgba(168, 85, 247, 0.6);
    box-shadow: 0 0 0 3px rgba(168, 85, 247, 0.18);
  }

  button {
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;
  }

  button,
  button *,
  [role='button'],
  [role='button'] * {
    -webkit-user-select: none;
    user-select: none;
  }

  button:not(:disabled):active {
    transform: translateY(1px);
  }

  * {
    scrollbar-width: thin;
    scrollbar-color: rgba(139, 92, 246, 0.55) rgba(241, 245, 249, 0.75);
  }

  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  *::-webkit-scrollbar-track {
    background: rgba(241, 245, 249, 0.7);
    border-radius: 999px;
  }

  *::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(167, 139, 250, 0.8), rgba(99, 102, 241, 0.75));
    border: 2px solid rgba(241, 245, 249, 0.9);
    border-radius: 999px;
  }

  *::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(147, 51, 234, 0.86), rgba(79, 70, 229, 0.82));
  }

  ::selection {
    background: rgba(168, 85, 247, 0.25);
  }
}

.yRemoteSelection {
  background-color: rgba(14, 165, 233, 0.35);
}

.yRemoteSelectionHead {
  border-left: 2px solid rgba(14, 165, 233, 0.9);
  border-top: 2px solid rgba(14, 165, 233, 0.9);
  border-bottom: 2px solid rgba(14, 165, 233, 0.9);
  box-sizing: border-box;
}

.collab-selection-overlay {
  scrollbar-width: none;
}

.collab-selection-overlay::-webkit-scrollbar {
  display: none;
}

.monaco-editor .collab-debug-active-line {
  background: linear-gradient(90deg, rgba(56, 189, 248, 0.18), rgba(56, 189, 248, 0.06));
  border-left: 2px solid rgba(56, 189, 248, 0.92);
  box-sizing: border-box;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph,
.monaco-editor .margin .collab-debug-active-glyph {
  position: relative !important;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph {
  transition: filter 0.2s ease;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph:hover {
  filter: brightness(1.06);
}

.monaco-editor .margin .collab-debug-active-glyph {
  animation: collabDebugPulse 1.35s ease-in-out infinite;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph::before,
.monaco-editor .margin .collab-debug-active-glyph::before {
  content: '';
  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--collab-breakpoint-size, 12px);
  height: var(--collab-breakpoint-size, 12px);
  border-radius: 999px;
  box-sizing: border-box;
  pointer-events: none;
}

.monaco-editor .margin .collab-debug-breakpoint-glyph::before {
  background: radial-gradient(circle at 30% 28%, #ffe4ea 0%, #fb7185 34%, #e11d48 70%, #9f1239 100%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    inset 0 0 0 1px rgba(136, 19, 55, 0.56),
    0 0 var(--collab-breakpoint-glow, 8px) rgba(225, 29, 72, 0.55),
    0 0 0 var(--collab-breakpoint-ring, 2px) rgba(244, 63, 94, 0.18);
}

.monaco-editor .margin .collab-debug-active-glyph::before {
  background: radial-gradient(circle at 30% 28%, #ecfeff 0%, #67e8f9 38%, #06b6d4 68%, #0369a1 100%);
  border: 1px solid rgba(240, 249, 255, 0.85);
  box-shadow:
    inset 0 0 0 1px rgba(14, 116, 144, 0.42),
    0 0 calc(var(--collab-breakpoint-glow, 8px) + 2px) rgba(14, 165, 233, 0.68),
    0 0 0 var(--collab-breakpoint-ring, 2px) rgba(56, 189, 248, 0.2);
}

@keyframes collabDebugPulse {
  0%, 100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.14);
  }
}

.monaco-editor .collab-debug-inline-hint {
  color: rgba(148, 163, 184, 0.88) !important;
  font-style: italic;
  font-size: 0.92em;
  letter-spacing: 0.01em;
  opacity: 0.95;
}

.monaco-editor .inline-inlay-hint,
.monaco-editor .inline-hints .inline-hint,
.monaco-editor .editorInlayHint {
  color: rgba(148, 163, 184, 0.92) !important;
  font-style: italic;
  background: transparent !important;
  border: none !important;
}

@layer components {
  .app-shell {
    background:
      radial-gradient(circle at -10% -20%, rgba(236, 72, 153, 0.11), transparent 38%),
      radial-gradient(circle at 18% 0%, rgba(59, 130, 246, 0.12), transparent 40%),
      radial-gradient(circle at 82% -8%, rgba(168, 85, 247, 0.13), transparent 48%),
      repeating-linear-gradient(-32deg, rgba(255, 255, 255, 0.35) 0 1px, transparent 1px 34px),
      linear-gradient(180deg, rgba(248, 250, 252, 0.93), rgba(241, 245, 249, 0.97));
  }

  .sidebar-shell {
    position: relative;
    isolation: isolate;
    background:
      radial-gradient(circle at 10% -8%, rgba(244, 114, 182, 0.18), transparent 38%),
      radial-gradient(circle at 96% -10%, rgba(59, 130, 246, 0.18), transparent 42%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(243, 239, 255, 0.97));
    border-right: 1px solid rgba(167, 139, 250, 0.24);
    box-shadow: 0 24px 46px rgba(15, 23, 42, 0.14), inset -1px 0 0 rgba(255, 255, 255, 0.74);
    backdrop-filter: blur(20px) saturate(118%);
    -webkit-backdrop-filter: blur(20px) saturate(118%);
  }

  .sidebar-shell::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
      linear-gradient(115deg, rgba(255, 255, 255, 0.46), transparent 38%),
      repeating-linear-gradient(-24deg, rgba(139, 92, 246, 0.055) 0 1px, transparent 1px 20px);
    opacity: 0.9;
  }

  .sidebar-shell::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.38), transparent 45%);
  }

  .sidebar-aurora {
    position: absolute;
    border-radius: 999px;
    filter: blur(42px);
    opacity: 0.58;
    pointer-events: none;
  }

  .sidebar-aurora--top {
    width: 210px;
    height: 210px;
    top: -96px;
    left: -72px;
    background: radial-gradient(circle, rgba(244, 114, 182, 0.42) 0%, rgba(168, 85, 247, 0.1) 55%, transparent 73%);
  }

  .sidebar-aurora--bottom {
    width: 230px;
    height: 230px;
    right: -118px;
    bottom: -112px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.32) 0%, rgba(168, 85, 247, 0.11) 48%, transparent 74%);
  }

  .sidebar-grid {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(circle at 0 0, rgba(148, 163, 184, 0.08) 0 1px, transparent 1px) 0 0/16px 16px;
    opacity: 0.35;
  }

  .sidebar-top,
  .sidebar-footer {
    position: relative;
    z-index: 2;
  }

  .sidebar-brand-mark {
    box-shadow:
      0 15px 24px rgba(124, 58, 237, 0.26),
      inset 0 1px 0 rgba(255, 255, 255, 0.34);
  }

  .sidebar-brand-dot {
    animation: sidebarPulse 2.8s ease-out infinite;
  }

  .sidebar-brand-title {
    letter-spacing: -0.015em;
    text-shadow: 0 6px 18px rgba(124, 58, 237, 0.16);
  }

  .sidebar-brand-subtitle {
    margin-top: 0.28rem;
  }

  .sidebar-nav {
    position: relative;
    z-index: 2;
    scrollbar-gutter: stable both-edges;
    scrollbar-width: thin;
    scrollbar-color: rgba(124, 58, 237, 0.5) rgba(255, 255, 255, 0.4);
  }

  .sidebar-nav::-webkit-scrollbar {
    width: 8px;
  }

  .sidebar-nav::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.45);
    border-radius: 999px;
  }

  .sidebar-nav::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(168, 85, 247, 0.85), rgba(99, 102, 241, 0.78));
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.75);
  }

  .sidebar-nav-stack {
    position: relative;
    z-index: 2;
  }

  .sidebar-nav-item {
    position: relative;
    isolation: isolate;
    animation: fadeUp 0.42s ease-out both;
    animation-delay: calc(var(--item-index, 0) * 55ms);
  }

  .sidebar-nav-item::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.7rem;
    bottom: 0.7rem;
    width: 3px;
    border-radius: 999px;
    background: linear-gradient(180deg, rgba(139, 92, 246, 0.95), rgba(217, 70, 239, 0.85));
    opacity: 0;
    transform: scaleY(0.72);
    transform-origin: center;
    transition: opacity 0.2s ease, transform 0.2s ease;
  }

  .sidebar-nav-item.is-active::before {
    opacity: 1;
    transform: scaleY(1);
  }

  .sidebar-nav-item:not(.is-active):hover::before {
    opacity: 0.45;
    transform: scaleY(0.95);
  }

  .sidebar-nav-icon {
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
  }

  .sidebar-nav-icon.is-active {
    box-shadow: 0 10px 20px rgba(124, 58, 237, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.62);
  }

  .sidebar-nav-label {
    letter-spacing: -0.012em;
  }

  .sidebar-nav-arrow {
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.62);
  }

  .sidebar-nav-arrow.is-active {
    box-shadow: 0 8px 14px rgba(124, 58, 237, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.52);
  }

  .sidebar-profile-card {
    position: relative;
    overflow: hidden;
  }

  .sidebar-profile-card::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(120deg, rgba(255, 255, 255, 0) 35%, rgba(255, 255, 255, 0.42) 50%, rgba(255, 255, 255, 0) 66%);
    transform: translateX(-120%);
    animation: sheen 1.4s ease-out 0.2s both;
  }

  .sidebar-logout {
    letter-spacing: 0.01em;
  }

  .sidebar-logout:hover {
    box-shadow: 0 12px 22px rgba(244, 63, 94, 0.17);
  }

  .sidebar-collapse-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.7rem;
    border: 1px solid rgba(167, 139, 250, 0.34);
    background: rgba(255, 255, 255, 0.9);
    color: rgba(109, 40, 217, 0.95);
    box-shadow:
      0 8px 18px rgba(124, 58, 237, 0.14),
      inset 0 1px 0 rgba(255, 255, 255, 0.82);
    transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.2s ease, background-color 0.2s ease, color 0.2s ease;
  }

  .sidebar-collapse-btn:hover {
    transform: translateY(calc(-50% - 1px));
    border-color: rgba(167, 139, 250, 0.5);
    background: rgba(255, 255, 255, 0.97);
    box-shadow:
      0 10px 20px rgba(124, 58, 237, 0.2),
      inset 0 1px 0 rgba(255, 255, 255, 0.9);
  }

  .sidebar-collapse-btn:not(:disabled):active {
    transform: translateY(calc(-50% + 1px));
  }

  .sidebar-collapse-btn:hover:not(:disabled):active {
    transform: translateY(-50%);
  }

  .desktop-nav-fab {
    position: fixed;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.42rem;
    left: 0.35rem;
    top: 50%;
    z-index: 48;
    transform: translateY(-50%) translateX(-10px);
    width: 3.7rem;
    padding: 0.56rem 0.34rem;
    border-radius: 1.18rem;
    border: 1px solid rgba(167, 139, 250, 0.36);
    background: linear-gradient(165deg, rgba(255, 255, 255, 0.93), rgba(248, 250, 252, 0.9));
    box-shadow:
      0 16px 34px rgba(15, 23, 42, 0.16),
      0 6px 14px rgba(124, 58, 237, 0.14);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.24s ease, transform 0.24s ease;
  }

  .desktop-nav-fab.is-visible {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(-50%) translateX(0);
  }

  .desktop-nav-fab__stack {
    display: flex;
    width: 100%;
    flex-direction: column;
    align-items: center;
    gap: 0.46rem;
  }

  .desktop-nav-fab__divider {
    width: 2.2rem;
    height: 1px;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(167, 139, 250, 0.06), rgba(167, 139, 250, 0.48), rgba(167, 139, 250, 0.06));
  }

  .desktop-nav-fab__toggle,
  .desktop-nav-fab__item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 3rem;
    height: 3rem;
    border-radius: 1.02rem;
    border: 1px solid rgba(196, 181, 253, 0.72);
    background: rgba(255, 255, 255, 0.9);
    color: rgb(124, 58, 237);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
    transition: transform 0.18s ease, border-color 0.2s ease, background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
  }

  .desktop-nav-fab__toggle:hover,
  .desktop-nav-fab__item:hover {
    transform: translateY(-1px);
    border-color: rgba(167, 139, 250, 0.86);
    background: rgba(255, 255, 255, 1);
    box-shadow:
      0 8px 16px rgba(124, 58, 237, 0.18),
      inset 0 1px 0 rgba(255, 255, 255, 0.9);
  }

  .desktop-nav-fab__item.is-active {
    border-color: rgba(167, 139, 250, 0.9);
    background: linear-gradient(145deg, rgba(124, 58, 237, 0.92), rgba(147, 51, 234, 0.86));
    color: rgb(250, 245, 255);
    box-shadow:
      0 10px 20px rgba(124, 58, 237, 0.34),
      inset 0 1px 0 rgba(255, 255, 255, 0.28);
  }

  .main-shell {
    transition: padding-left 0.28s ease;
  }

  .desktop-main-shifted {
    padding-left: 0;
  }

  @media (min-width: 768px) {
    .desktop-main-shifted {
      padding-left: calc(0.35rem + 3.7rem);
    }
  }

  .surface-card {
    background: linear-gradient(165deg, rgba(255, 255, 255, 0.96), rgba(255, 255, 255, 0.86));
    border: 1px solid rgba(148, 163, 184, 0.28);
    box-shadow: var(--shadow-soft);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
  }

.surface-card:hover {
  box-shadow: var(--shadow-lift);
}

.question-attachment-drop-card {
  position: relative;
}

.question-attachment-drop-card.is-dragging-attachments {
  border-color: rgba(168, 85, 247, 0.76) !important;
  box-shadow:
    var(--shadow-lift),
    0 0 0 3px rgba(168, 85, 247, 0.16),
    inset 0 0 0 1px rgba(168, 85, 247, 0.22);
}

.mock-task-attachment-drop-zone {
  position: relative;
  border-radius: 1rem;
  transition: box-shadow 0.18s ease, background-color 0.18s ease;
}

.mock-task-attachment-drop-zone.is-dragging-attachments {
  background-color: rgba(168, 85, 247, 0.06);
  box-shadow:
    0 0 0 3px rgba(168, 85, 247, 0.22),
    inset 0 0 0 1px rgba(168, 85, 247, 0.26);
}

.board-surface-card.surface-card {
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 0 !important;
}

.board-surface-card--fullscreen.surface-card {
  padding: 0.25rem !important;
}

.board-surface-card--main.surface-card {
  padding: 0 !important;
}

@media (min-width: 768px) {
  .board-surface-card--fullscreen.surface-card {
    padding: 0.5rem !important;
  }
}

.board-canvas-outline {
  border: 2px solid rgba(148, 163, 184, 0.28);
}

html[data-theme='dark'] .board-canvas-outline {
  border-color: rgba(148, 163, 184, 0.4);
}

  .surface-panel {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.93), rgba(255, 255, 255, 0.88));
    border: 1px solid rgba(148, 163, 184, 0.2);
    box-shadow: var(--shadow-panel);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }

  .progress-overview-card--compact {
    padding: 0.875rem;
    border-radius: 1.5rem;
    box-shadow:
      0 12px 30px rgba(99, 102, 241, 0.12),
      inset 0 1px 0 rgba(255, 255, 255, 0.58);
  }

  .progress-overview-meter--compact {
    padding: 0.75rem 1rem;
  }

  .progress-section-tabs {
    align-self: flex-start;
    box-shadow:
      0 10px 26px rgba(15, 23, 42, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.76);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }

  .progress-section-tabs--compact {
    margin-bottom: 0.1rem;
  }

  @media (min-width: 768px) {
    .progress-overview-card--compact {
      padding: 1rem 1.125rem;
    }

    .progress-section-tabs--compact {
      margin-top: -0.1rem;
    }
  }

  .progress-tests-grid {
    align-items: stretch;
  }

  .progress-topic-card {
    min-height: 100%;
    border-color: rgba(203, 213, 225, 0.72);
    box-shadow:
      0 14px 32px rgba(15, 23, 42, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.78);
  }

  .progress-topic-card::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 0;
    background:
      radial-gradient(circle at 0% 0%, rgba(168, 85, 247, 0.12), transparent 34%),
      linear-gradient(115deg, rgba(255, 255, 255, 0.32), transparent 42%);
    opacity: 0.68;
    pointer-events: none;
  }

  .progress-topic-card > * {
    position: relative;
    z-index: 1;
  }

  .notes-teacher-header,
  .notes-mobile-tools,
  .notes-empty-state {
    border-color: rgba(203, 213, 225, 0.62);
    background:
      radial-gradient(circle at 0% 0%, rgba(168, 85, 247, 0.1), transparent 34%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 252, 0.88));
    box-shadow:
      0 12px 28px rgba(15, 23, 42, 0.07),
      inset 0 1px 0 rgba(255, 255, 255, 0.78);
  }

  .notes-student-picker {
    flex-wrap: nowrap;
    min-height: 3.35rem;
    padding: 0.38rem 0.42rem 0.38rem 0.9rem;
    border-radius: 1.15rem;
    border: 1px solid rgba(167, 139, 250, 0.34);
    background: rgba(255, 255, 255, 0.76);
    box-shadow:
      0 12px 26px rgba(15, 23, 42, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.82);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
  }

  .notes-student-picker__label {
    flex: 0 0 auto;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgb(126, 34, 206);
  }

  .notes-student-picker__select {
    min-height: 2.6rem;
    border-radius: 0.95rem;
    border: 1px solid rgba(196, 181, 253, 0.48);
    background: rgba(255, 255, 255, 0.86);
    padding: 0 0.95rem;
    color: #334155;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.86);
  }

  .notes-landing-hero {
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border-color: rgba(167, 139, 250, 0.28);
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(250, 245, 255, 0.72));
    box-shadow:
      0 10px 22px rgba(88, 28, 135, 0.09),
      inset 0 1px 0 rgba(255, 255, 255, 0.82);
  }

  .notes-landing-hero__body,
  .notes-landing-hero__header {
    position: relative;
