@keyframes mockAnswerBurstStage {
  0% { opacity: 0; }
  12% { opacity: 1; }
  76% { opacity: 1; }
  100% { opacity: 0; }
}

@keyframes mockAnswerBurstWash {
  0% { opacity: 0; transform: scale(0.76) rotate(0deg); }
  18% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.18) rotate(54deg); }
}

@keyframes mockAnswerBurstRing {
  0% { opacity: 0; transform: scale(0.28); }
  18% { opacity: 0.95; }
  100% { opacity: 0; transform: scale(1.75); }
}

@keyframes mockAnswerBurstBadge {
  0% { opacity: 0; transform: translateY(18px) scale(0.72) rotate(-5deg); }
  22% { opacity: 1; transform: translateY(0) scale(1.12) rotate(2deg); }
  48% { transform: translateY(-2px) scale(0.98) rotate(0deg); }
  78% { opacity: 1; transform: translateY(-6px) scale(1); }
  100% { opacity: 0; transform: translateY(-26px) scale(0.9); }
}

@keyframes mockAnswerBurstParticle {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.35) rotate(0deg);
  }
  14% { opacity: 1; }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(0.18) rotate(var(--rot));
  }
}

.mock-artifact-drop {
  --artifact-main: #facc15;
  --artifact-hot: #22d3ee;
  --artifact-deep: #7c3aed;
  --artifact-ink: #ffffff;
  position: fixed;
  inset: 0;
  z-index: 1500;
  display: grid;
  place-items: center;
  overflow: hidden;
  pointer-events: none;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 47%, color-mix(in srgb, var(--artifact-main), transparent 78%), transparent 25%),
    radial-gradient(circle at 50% 47%, rgba(255, 255, 255, 0.12), transparent 11%),
    radial-gradient(circle at 18% 78%, color-mix(in srgb, var(--artifact-deep), transparent 76%), transparent 30%),
    linear-gradient(135deg, rgba(2, 6, 23, 0.84), rgba(15, 23, 42, 0.64));
  animation: mockArtifactDropStage 3.8s ease both;
}

.mock-artifact-drop--rank-s {
  --artifact-main: #fb7185;
  --artifact-hot: #f97316;
  --artifact-deep: #be123c;
}

.mock-artifact-drop--rank-a {
  --artifact-main: #c084fc;
  --artifact-hot: #22d3ee;
  --artifact-deep: #7c3aed;
}

.mock-artifact-drop--rank-b {
  --artifact-main: #38bdf8;
  --artifact-hot: #2dd4bf;
  --artifact-deep: #2563eb;
}

.mock-artifact-drop--rank-c {
  --artifact-main: #a3e635;
  --artifact-hot: #38bdf8;
  --artifact-deep: #475569;
}

.mock-artifact-drop::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 47%;
  width: 154vmax;
  height: 154vmax;
  z-index: -2;
  border-radius: 999px;
  background:
    radial-gradient(circle, transparent 0 18%, color-mix(in srgb, var(--artifact-main), transparent 72%) 19% 21%, transparent 23% 35%, color-mix(in srgb, var(--artifact-hot), transparent 78%) 36% 37%, transparent 39%),
    conic-gradient(
      from 0deg,
      transparent 0deg,
      color-mix(in srgb, var(--artifact-hot), transparent 74%) 22deg,
      transparent 52deg,
      color-mix(in srgb, var(--artifact-main), transparent 68%) 108deg,
      transparent 138deg,
      color-mix(in srgb, var(--artifact-deep), transparent 72%) 212deg,
      transparent 250deg,
      color-mix(in srgb, var(--artifact-hot), transparent 76%) 318deg,
      transparent 360deg
    );
  filter: blur(1px);
  mix-blend-mode: screen;
  opacity: 0;
  animation: mockArtifactDropWash 3.4s cubic-bezier(0.16, 0.92, 0.24, 1) both;
}

.mock-artifact-drop::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(circle at 50% 47%, transparent 0 14%, rgba(255, 255, 255, 0.18) 14.4% 14.8%, transparent 15.4% 28%, color-mix(in srgb, var(--artifact-main), transparent 82%) 28.4% 29%, transparent 30%),
    radial-gradient(circle at 50% 47%, color-mix(in srgb, var(--artifact-hot), transparent 86%), transparent 39%),
    radial-gradient(circle at 64% 28%, rgba(255, 255, 255, 0.12), transparent 8%),
    radial-gradient(circle at 28% 66%, color-mix(in srgb, var(--artifact-main), transparent 84%), transparent 10%);
  mix-blend-mode: screen;
  opacity: 0;
  animation: mockArtifactDropBeams 3.2s ease both;
}

.mock-artifact-drop__orbit {
  position: absolute;
  left: 50%;
  top: 47%;
  border: 1px solid color-mix(in srgb, var(--artifact-main), transparent 34%);
  border-radius: 999px;
  box-shadow:
    0 0 34px color-mix(in srgb, var(--artifact-main), transparent 38%),
    inset 0 0 42px color-mix(in srgb, var(--artifact-hot), transparent 76%);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.3);
}

.mock-artifact-drop__orbit--outer {
  width: min(74vmin, 42rem);
  aspect-ratio: 1;
  animation: mockArtifactDropOrbit 2.7s cubic-bezier(0.18, 0.9, 0.2, 1) 0.08s both;
}

.mock-artifact-drop__orbit--inner {
  width: min(48vmin, 28rem);
  aspect-ratio: 1;
  border-color: color-mix(in srgb, var(--artifact-hot), transparent 34%);
  animation: mockArtifactDropOrbit 2.45s cubic-bezier(0.18, 0.9, 0.2, 1) 0.18s both reverse;
}

.mock-artifact-drop__card {
  position: relative;
  z-index: 3;
  display: grid;
  width: min(88vw, 28rem);
  justify-items: center;
  gap: 0.74rem;
