}

.mock-artifact-drop__card::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 46%;
  width: min(66vmin, 31rem);
  aspect-ratio: 1;
  z-index: -1;
  border: 1px solid color-mix(in srgb, var(--artifact-main), transparent 58%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.2), transparent 18%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-main), transparent 70%), transparent 54%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-deep), transparent 78%), transparent 70%);
  box-shadow:
    0 0 80px color-mix(in srgb, var(--artifact-main), transparent 50%),
    inset 0 0 54px rgba(255, 255, 255, 0.1);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.72);
