  aspect-ratio: 1;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--artifact-hot), transparent 34%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.38), transparent 29%),
    radial-gradient(circle, color-mix(in srgb, var(--artifact-main), transparent 66%), transparent 63%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.04));
  color: color-mix(in srgb, var(--artifact-main), #ffffff 20%);
  box-shadow:
    0 0 54px color-mix(in srgb, var(--artifact-main), transparent 34%),
    0 0 110px color-mix(in srgb, var(--artifact-hot), transparent 68%),
