    drop-shadow(0 0 24px color-mix(in srgb, var(--artifact-main), transparent 20%));
}

.mock-artifact-drop__name {
  max-width: 100%;
  color: #ffffff;
  font-size: clamp(1.55rem, 5vmin, 2.85rem);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1.02;
  overflow-wrap: anywhere;
  text-shadow:
    0 0 18px color-mix(in srgb, var(--artifact-main), transparent 28%),
    0 3px 18px rgba(0, 0, 0, 0.36);
