@media (max-width: 640px) {
  .mock-exam-artifact-hint {
    border-radius: 1rem;
    padding: 0.5rem 0.64rem;
    font-size: 0.72rem;
  }

  .mock-artifact-drop__card {
    width: min(92vw, 22rem);
    border-radius: 1.15rem;
  }

  .mock-chest-stage {
    min-height: 94vh;
    padding: 3.75rem 0.85rem 1rem;
  }

  .mock-chest {
    width: min(18rem, 82vw);
    height: min(14.6rem, 66vw);
  }

  .mock-chest.mock-chest--image {
    width: min(22rem, 92vw);
    height: min(18rem, 78vw);
    margin: -0.5rem 0 -1.65rem;
  }

  .mock-chest-coins {
    --coin-prize-x: 0px;
    --coin-prize-y: -30vh;
  }

  .mock-chest-artifacts {
    top: 4.1rem;
    width: min(98vw, 27rem);
    height: 16.4rem;
  }

  .mock-chest-artifact {
    --artifact-x: -50%;
    top: 1.55rem;
    width: min(10.7rem, 43vw);
    min-height: 10.2rem;
    padding: 0.88rem 0.68rem 0.9rem;
    border-radius: 1.15rem;
  }

  .mock-chest-artifact:nth-child(2) {
    --artifact-x: 3%;
    --artifact-curve-x: -12%;
  }

  .mock-chest-artifacts--single .mock-chest-artifact:first-child {
    --artifact-x: -50%;
    --artifact-curve-x: -50%;
    --artifact-rotate: 0deg;
  }

  .mock-chest-artifacts--pair .mock-chest-artifact:first-child {
    --artifact-x: -104%;
    --artifact-curve-x: -86%;
    --artifact-rotate: -1deg;
  }

  .mock-chest-artifacts--pair .mock-chest-artifact:nth-child(2) {
    --artifact-x: 5%;
    --artifact-curve-x: -8%;
    --artifact-rotate: 1deg;
  }

  .mock-chest-artifacts--trio .mock-chest-artifact:first-child {
    --artifact-x: -122%;
    --artifact-curve-x: -92%;
    --artifact-rotate: -1.4deg;
  }

  .mock-chest-artifacts--trio .mock-chest-artifact:nth-child(2) {
    --artifact-x: -50%;
    --artifact-curve-x: -50%;
    --artifact-rotate: 0deg;
  }

  .mock-chest-artifacts--trio .mock-chest-artifact:nth-child(3) {
    --artifact-x: 22%;
    --artifact-curve-x: -2%;
    --artifact-rotate: 1.4deg;
  }

  .mock-chest-artifact:only-child {
    --artifact-x: -50%;
  }

  .mock-chest-artifact__rank {
    right: 0.52rem;
    top: 0.5rem;
    width: 1.85rem;
    height: 1.85rem;
    font-size: 0.7rem;
  }

  .mock-chest-artifact__image {
