    height: 4.75rem;
  }

  .mock-chest-artifact__name {
    margin-top: 0.66rem;
    font-size: 0.78rem;
  }

  .mock-chest-artifact__title {
    margin-top: 0.34rem;
    padding: 0.22rem 0.42rem;
    font-size: 0.56rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mock-answer-burst::before,
  .mock-answer-burst__ring,
  .mock-answer-burst__particle,
  .mock-artifact-drop::before,
  .mock-artifact-drop::after,
  .mock-artifact-drop__orbit,
  .mock-artifact-drop__shard {
    display: none;
  }

  .mock-answer-burst__badge {
    animation: fadeSoft 0.65s ease both;
  }

  .mock-artifact-drop,
  .mock-artifact-drop__card,
  .mock-artifact-drop__image-shell {
    animation-duration: 0.65s;
  }

  .mock-chest-overlay *,
  .mock-chest-overlay *::before,
  .mock-chest-overlay *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

