.theme-toggle {
  position: fixed;
  top: auto;
  bottom: calc(env(safe-area-inset-bottom) + 0.85rem);
  right: 0.7rem;
  z-index: 1400;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  border-radius: 999px;
  border: 1px solid rgba(124, 58, 237, 0.28);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.9), rgba(243, 232, 255, 0.88));
  color: #5b21b6;
  padding: 0.44rem;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  box-shadow: 0 10px 28px rgba(124, 58, 237, 0.2), 0 4px 10px rgba(15, 23, 42, 0.16);
  backdrop-filter: blur(12px) saturate(132%);
  -webkit-backdrop-filter: blur(12px) saturate(132%);
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.2s ease, gap 0.2s ease, padding 0.2s ease;
}

.theme-toggle:hover {
  transform: translateY(-1px);
  gap: 0.42rem;
  padding: 0.44rem 0.74rem 0.44rem 0.48rem;
  box-shadow: 0 14px 34px rgba(124, 58, 237, 0.26), 0 6px 14px rgba(15, 23, 42, 0.2);
}

.theme-toggle__icon-wrap {
  display: inline-grid;
  place-items: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 999px;
  background: linear-gradient(145deg, rgba(139, 92, 246, 0.24), rgba(59, 130, 246, 0.22));
  color: inherit;
}

.theme-toggle__label {
  line-height: 1;
  max-width: 0;
  opacity: 0;
  white-space: nowrap;
  transform: translateX(6px);
  transition: max-width 0.2s ease, opacity 0.2s ease, transform 0.2s ease;
}

.python-logo-icon {
  display: inline-block;
  flex-shrink: 0;
  object-fit: contain;
  color: inherit;
}

.theme-toggle:hover .theme-toggle__label,
.theme-toggle:focus-visible .theme-toggle__label {
  max-width: 7rem;
  opacity: 1;
  transform: translateX(0);
}

.theme-toggle--inline {
  position: static;
  top: auto;
  right: auto;
  bottom: auto;
  z-index: auto;
  width: 2.3rem;
  height: 2.3rem;
  padding: 0.36rem;
  gap: 0;
  border-radius: 0.78rem;
  box-shadow: 0 6px 14px rgba(124, 58, 237, 0.16), 0 2px 8px rgba(15, 23, 42, 0.12);
  backdrop-filter: blur(8px) saturate(120%);
  -webkit-backdrop-filter: blur(8px) saturate(120%);
}

.theme-toggle--inline:hover,
.theme-toggle--inline:focus-visible {
  transform: none;
  gap: 0;
  padding: 0.36rem;
}

.theme-toggle--inline .theme-toggle__label {
  display: none;
}

.theme-toggle--inline .theme-toggle__icon-wrap {
  width: 1.5rem;
  height: 1.5rem;
}

.theme-toggle--desktop {
  display: none !important;
}

html[data-theme='dark'] .theme-toggle {
  border-color: rgba(56, 189, 248, 0.34);
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.84), rgba(30, 41, 59, 0.8));
  color: rgb(226, 232, 240);
  box-shadow: 0 14px 36px rgba(2, 6, 23, 0.6), 0 8px 22px rgba(8, 47, 73, 0.34);
