      radial-gradient(90px 300px at -18px 82%, rgba(129, 140, 248, 0.16), transparent 74%);
  }

  html[data-theme='dark'] .main-shell::after {
    background: linear-gradient(180deg, rgba(148, 163, 184, 0.32), rgba(51, 65, 85, 0.36), rgba(148, 163, 184, 0.24));
