.student-leaderboard-section .student-leaderboard-profile-theme__hint {
  position: relative;
  display: inline-flex;
  width: 1.1rem;
  height: 1.1rem;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(168, 85, 247, 0.26);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  color: #7c3aed;
  cursor: help;
  font: inherit;
  line-height: 1;
  outline: none;
  padding: 0;
  text-transform: none;
}

.student-leaderboard-section .student-leaderboard-profile-theme__hint-popover {
  position: absolute;
  top: calc(100% + 0.55rem);
  left: 50%;
  z-index: 30;
  display: grid;
  width: min(18rem, calc(100vw - 2rem));
  gap: 0.35rem;
  border: 1px solid rgba(168, 85, 247, 0.18);
  border-radius: 0.9rem;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 0.9rem 2rem rgba(88, 28, 135, 0.14);
  color: #4c1d95;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 1.32;
  opacity: 0;
  padding: 0.65rem 0.7rem;
  pointer-events: none;
  text-transform: none;
  transform: translate(-50%, -0.25rem);
  transition:
    opacity 0.16s ease,
    visibility 0.16s ease,
    transform 0.16s ease;
  visibility: hidden;
  white-space: normal;
}

.student-leaderboard-section .student-leaderboard-profile-theme__hint-popover::before {
  content: '';
  position: absolute;
  top: -0.35rem;
  left: 50%;
  width: 0.65rem;
  height: 0.65rem;
  border-top: 1px solid rgba(168, 85, 247, 0.18);
  border-left: 1px solid rgba(168, 85, 247, 0.18);
  background: inherit;
  transform: translateX(-50%) rotate(45deg);
}

