  inset: 0;
  z-index: 2;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--legendary-rainbow-angle),
    rgba(56, 189, 248, 0.74),
    rgba(168, 85, 247, 0.76),
    rgba(244, 114, 182, 0.82),
    rgba(251, 191, 36, 0.72),
    rgba(74, 222, 128, 0.7),
    rgba(56, 189, 248, 0.74)
  );
  opacity: 0.5;
  filter: saturate(1.2) brightness(1.08);
  pointer-events: none;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation:
    artifactLegendaryRainbowBorder 7.2s linear infinite,
    artifactLegendaryBorderBreath 3.1s ease-in-out infinite;
