@keyframes artifactLegendaryTeaserIn {
  from {
    opacity: 0;
    transform: translateY(0.75rem) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes artifactLegendarySweep {
  0%, 70%, 100% {
    transform: translateX(-35%) rotate(-12deg);
    opacity: 0;
  }
  82% {
    transform: translateX(22%) rotate(10deg);
    opacity: 0.58;
  }
}

@keyframes artifactLegendaryRainbowBorder {
  to {
    --legendary-rainbow-angle: 360deg;
  }
}

@keyframes artifactLegendaryBorderBreath {
  0%, 100% {
    opacity: var(--legendary-border-opacity-low, 0.52);
  }
  50% {
    opacity: var(--legendary-border-opacity-high, 0.9);
  }
}

@keyframes artifactLegendaryPulse {
  0%, 100% {
    opacity: 0.62;
    transform: scale(0.94);
  }
  50% {
    opacity: 0.95;
    transform: scale(1.08);
  }
}

@keyframes artifactLegendaryOrbit {
  to {
    transform: rotate(360deg);
  }
}

@keyframes artifactDetailBackdropIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes artifactDetailCardIn {
  from {
    opacity: 0;
    transform: translateY(1.2rem) scale(0.94) rotateX(8deg);
