  .student-artifact-upgrade-showcase__artifact::after,
  .student-artifact-upgrade-showcase__burst,
  .student-artifact-upgrade-showcase__level,
  .student-artifact-upgrade-showcase__results {
    animation: none !important;
    transition: none !important;
