.mock-classic-lock-card {
  border-color: rgba(56, 189, 248, 0.46) !important;
  background:
    linear-gradient(135deg, rgba(15, 23, 42, 0.98), rgba(30, 41, 59, 0.94) 48%, rgba(8, 47, 73, 0.82)),
    repeating-linear-gradient(-32deg, rgba(56, 189, 248, 0.055) 0 1px, transparent 1px 18px) !important;
  color: rgb(248, 250, 252);
  box-shadow:
    0 10px 0 rgba(2, 6, 23, 0.48),
    0 32px 70px rgba(2, 6, 23, 0.52),
